"""Make a self-contained read-only preview from actual Python analysis results."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
a=json.loads((ROOT/'demo'/'all_results.json').read_text())
content='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TitaniumGuard — demonstration</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f1ec;color:#172a35;font-family:system-ui,-apple-system,"PingFang SC","Microsoft YaHei",sans-serif}header{background:#172a35;color:#fff;padding:38px max(6vw,20px)}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;color:#d4aa81}h1{font-size:42px;margin:8px 0}header p{color:#d1d9dc;max-width:780px;line-height:1.6}main{max-width:1120px;margin:auto;padding:24px}nav{display:flex;gap:8px;flex-wrap:wrap}button{cursor:pointer;border:1px solid #b6bfc3;border-radius:6px;padding:12px 19px;background:#fff;color:#172a35;font:inherit;font-weight:600}button.active{background:#172a35;color:white;border-color:#172a35}.status{margin:22px 0;background:#fff;border-left:5px solid #36735b;padding:19px;border-radius:5px}.status.bad{border-color:#b74734}.status.warn{border-color:#b47729}.status h2{font-size:20px;margin:0 0 8px}.status p{line-height:1.6;margin:0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.card,.panel{background:#fff;border:1px solid #d9dcd9;border-radius:8px;padding:19px}.label{font-size:12px;color:#52646d}.number{font-size:29px;font-weight:650;margin-top:7px}.sub{font-size:11px;color:#60727a;margin-top:7px}.graphs{display:grid;grid-template-columns:1.5fr 1fr;gap:15px;margin-top:16px}.panel h3{margin:0 0 6px;font-size:16px}.panel p{font-size:12px;color:#62717a;line-height:1.6}svg{width:100%;height:auto}footer{padding:24px 0;font-size:12px;line-height:1.8;color:#52646d}summary{cursor:pointer;font-weight:650}details{margin-top:20px;padding:20px;background:#fff;border-radius:8px}details p{line-height:1.7}code{background:#eef0ed;padding:2px 6px;border-radius:4px}.pill{display:inline-block;font-size:11px;color:#e4c29e;border:1px solid #647079;border-radius:30px;padding:6px 12px;margin-bottom:10px}a{color:#315f79}@media(max-width:700px){h1{font-size:33px}.cards{grid-template-columns:1fr 1fr}.graphs{grid-template-columns:1fr}main{padding:18px}}</style>
<header><div class="pill">CORNELL SIX SIGMA · VIRTUAL DL</div><div class="eyebrow">3D Printing for Aerospace</div><h1>TitaniumGuard</h1><p>A quality engineer’s workbench for monitoring titanium coupon strength. This read-only preview displays results computed by the included Python code. The full application supports CSV upload, build logging and report export.</p></header>
<main><nav><button data-case="stable_capable">01 · Stable process</button><button data-case="mean_shift">02 · Mean shift</button><button data-case="stable_incapable">03 · Low margin</button></nav><div id="status" class="status"></div><div class="cards" id="cards"></div><div class="graphs"><section class="panel"><h3>Build mean · X̄ chart</h3><p>Frozen limits from builds 1–25. Red points indicate a mean or range signal.</p><div id="mean"></div></section><section class="panel"><h3>Within-build spread · R chart</h3><p>Inspect spread before interpreting the mean chart.</p><div id="range"></div></section></div><section class="panel" style="margin-top:16px"><h3>How to read this scenario</h3><p id="read" style="font-size:14px"></p></section><details><summary>What was verified, and what remains</summary><p>The statistical core passed 50 numerical and boundary tests, plus an independent read-only formula review. Nine API integration checks also passed. The full app, tests, synthetic data generator, codebook, English presentation script and Chinese guide are in the project package.</p><p>Run <code>bash app/testme.sh</code> from the unzipped project to open the full application. Publishing the public GitHub repository, deploying to the course Posit Connect account and submitting on Devpost require actual account access; this preview is not evidence of those actions.</p></details><details><summary>Chinese presentation notes</summary><p>① 正常案例：没有发现控制信号，基线能力指数高于演示目标。② 突发变化：第26批开始报警；基线Cpl仍高，但不能用它证明变化后的过程有能力。③ 低裕量：没有发现过程变化，但平均强度过于接近最低要求，Cpl不足。重点是“稳定”和“有能力”是两件事。</p><p>全部数据都是明确标注的模拟数据。900 MPa和1.33是演示设置，不是航空标准；只有强度下限时用Cpl，不能编造上限来算Cp。控制界限来自基线，规格要求来自客户。</p></details><footer><strong>Synthetic demonstration only.</strong> Selected seed42 illustrates the intended scenarios; it is not an unbiased alarm-performance simulation. LSL900MPa and target1.33 are invented teaching settings. Capability interpretation requires representative independent data, approximate normality and a qualified measurement plan. Coupons do not establish individual bracket release or airworthiness. <a href="https://six-sigma-hackathon.devpost.com/">Official challenge</a> · <a href="https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc321.htm">NIST chart formulas</a></footer></main>
<script>const DATA=__DATA__;
const notes={stable_capable:'No control signal was detected in this selected synthetic fixture. The historical baseline Cpl is above the illustrative target. This is conditional on the sampling, distribution and measurement assumptions; it is not a part-release approval.',mean_shift:'The synthetic strength mean drops at B026. All 15 monitoring builds are flagged. The baseline limits and Cpl stay unchanged, so the changed process cannot redefine its own normal behavior. The higher logged oxygen value is an investigation clue, not proof of causation.',stable_incapable:'This fixture has no detected change, but its baseline strength margin is too small. A predictable process can still fail to meet the chosen capability target. Observed nonconformance is measured from the samples, not a forecast.'};
function chart(a,key){const w=650,h=280,p={l:54,r:22,t:20,b:38},values=a.groups.map(g=>key==='xbar'?g.mean:g.range),limits=a.limits[key],lo=Math.min(...values,limits.lcl),hi=Math.max(...values,limits.ucl),pad=(hi-lo)*.16||1,min=lo-pad,max=hi+pad,x=i=>p.l+i*(w-p.l-p.r)/(values.length-1),y=v=>h-p.b-(v-min)*(h-p.t-p.b)/(max-min);let s=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${key} control chart in MPa"><rect x="${p.l}" y="${p.t}" width="${x(a.metadata.baseline_builds-1)-p.l}" height="${h-p.t-p.b}" fill="#eef1ec"/>`;for(let i=0;i<5;i++){let v=min+(max-min)*i/4;s+=`<line x1="${p.l}" y1="${y(v)}" x2="${w-p.r}" y2="${y(v)}" stroke="#e0e5e4"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#687b83">${v.toFixed(0)}</text>`}for(let k of ['lcl','cl','ucl'])s+=`<line x1="${p.l}" y1="${y(limits[k])}" x2="${w-p.r}" y2="${y(limits[k])}" stroke="${k==='cl'?'#6d8791':'#b47750'}" stroke-dasharray="${k==='cl'?'':'5 4'}"/><text x="${w-p.r-2}" y="${y(limits[k])-5}" text-anchor="end" font-size="10" fill="#8f6b4d">${k.toUpperCase()} ${limits[k].toFixed(2)}</text>`;s+=`<polyline points="${values.map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="#315f79" stroke-width="1.8"/>`;values.forEach((v,i)=>s+=`<circle cx="${x(i)}" cy="${y(v)}" r="3.2" fill="${a.groups[i].signals.length?'#bb4b38':'#315f79'}"><title>${a.groups[i].id}: ${v.toFixed(2)} MPa</title></circle>`);[0,9,19,24,29,39].forEach(i=>s+=`<text x="${x(i)}" y="${h-15}" text-anchor="middle" font-size="11" fill="#687b83">${i+1}</text>`);return s+'<text x="13" y="14" font-size="10" fill="#687b83">MPa</text></svg>'}
function select(name){const a=DATA[name],bad=a.status==='process_shift',warn=a.status==='below_target';document.querySelectorAll('button[data-case]').forEach(b=>b.classList.toggle('active',b.dataset.case===name));const st=document.getElementById('status');st.className='status'+(bad?' bad':warn?' warn':'');st.innerHTML='<h2>'+a.status_label+'</h2><p>'+a.recommendation+'</p>';const obs=a.observed.monitoring;const cards=[['Historical baseline Cpl',a.baseline.index_value.toFixed(3),'Study target 1.33 · lower limit only'],['Flagged builds',a.signals.total,'40 builds · 25 reference + 15 monitoring'],['Monitoring nonconforming',obs.nonconforming+' / '+obs.n,'Observed coupons · not predicted risk'],['Within-build σ',a.baseline.sigma_within.toFixed(2)+' MPa','Baseline R̄ / d₂ · n = 5']];document.getElementById('cards').innerHTML=cards.map(c=>'<div class="card"><div class="label">'+c[0]+'</div><div class="number">'+c[1]+'</div><div class="sub">'+c[2]+'</div></div>').join('');document.getElementById('mean').innerHTML=chart(a,'xbar');document.getElementById('range').innerHTML=chart(a,'range');document.getElementById('read').textContent=notes[name]}
document.querySelectorAll('button[data-case]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.case)));select('stable_capable');</script></html>'''
out=ROOT/'demo'/'TitaniumGuard_Demo.html'
out.write_text(content.replace('__DATA__',json.dumps(a,ensure_ascii=False).replace('</','<\\/')))
print(out)
